ons.name_en,\n    NULL::text AS bank_name,\n    NULL::text AS account_number,\n    finance_cash_locations.is_active\n   FROM finance_cash_locations\n  WHERE treasury_can_view(NULL::uuid, finance_cash_locations.id);"},"finance_treasury_balances":{"options":["security_invoker=true"],"definition":" SELECT a.kind,\n    a.account_id,\n    a.bank_account_id,\n    a.cash_location_id,\n    a.name_th,\n    a.name_en,\n    a.bank_name,\n    a.account_number,\n    a.is_active,\n    b.currency,\n    b.opening_id,\n    b.opening_as_of,\n    b.opening_amount::numeric(14,2) AS opening_amount,\n    b.system_balance,\n    b.inflow,\n    b.outflow\n   FROM finance_treasury_accounts a\n     CROSS JOIN LATERAL expense_account_balance(a.bank_account_id, a.cash_location_id) b(currency, opening_id, opening_as_of, opening_amount, system_balance, inflow, outflow);"},"finance_payment_effective_invoice_allocations":{"options":["security_invoker=true"],"definition":" WITH allocation_legs AS (\n         SELECT allocation.payment_id,\n            allocation.invoice_id,\n            allocation.cash_allocated::numeric AS cash_delta,\n            allocation.wht_credit_allocated::numeric AS wht_delta\n           FROM finance_payment_invoice_allocations allocation\n        UNION ALL\n         SELECT reallocation.payment_id,\n            reallocation.source_invoice_id,\n            - reallocation.cash_moved::numeric,\n            - reallocation.wht_moved::numeric\n           FROM finance_payment_allocation_reallocations reallocation\n        UNION ALL\n         SELECT reallocation.payment_id,\n            reallocation.target_invoice_id,\n            reallocation.cash_moved::numeric AS cash_moved,\n            reallocation.wht_moved::numeric AS wht_moved\n           FROM finance_payment_allocation_reallocations reallocation\n        ), effective AS (\n         SELECT allocation_legs.payment_id,\n            allocation_legs.invoice_id,\n            sum(allocation_legs.cash_delta)::numeric(14,2) AS effective_cash_allocated,\n            sum(allocation_legs.wht_delta)::numeric(14,2) AS effective_wht_credit_allocated\n           FROM allocation_legs\n          GROUP BY allocation_legs.payment_id, allocation_legs.invoice_id\n        )\n SELECT payment_id,\n    invoice_id,\n    effective_cash_allocated,\n    effective_wht_credit_allocated,\n    (effective_cash_allocated + effective_wht_credit_allocated)::numeric(14,2) AS effective_settlement_total\n   FROM effective\n  WHERE effective_cash_allocated <> 0::numeric OR effective_wht_credit_allocated <> 0::numeric;"}}}'::jsonb value),actual as materialized(select jsonb_build_object('functions',f.value,'catalog',c.value,'views',(select coalesce(jsonb_object_agg(relname,jsonb_build_object('definition',pg_get_viewdef(oid,true),'options',reloptions)),'{}') from pg_class where relnamespace='public'::regnamespace and relkind='v' and relname in ('advisory_matters','cases','clients','finance_account_opening_balances','finance_bank_account_access','finance_bank_accounts','finance_cash_locations','finance_cash_transaction_audit_events','finance_cash_transactions','finance_direct_money_receipts','finance_expense_audit','finance_expense_obligation_waivers','finance_expense_obligations','finance_expense_request_audit','finance_expense_request_items','finance_expense_requests','finance_expense_settlements','finance_expenses','finance_invoice_items','finance_invoices','finance_outgoing_wht_obligations','finance_payable_entitlement_audit','finance_payable_entitlement_sources','finance_payable_entitlements','finance_payee_audit','finance_payee_destinations','finance_payees','finance_payment_allocation_reallocations','finance_payment_effective_invoice_allocations','finance_payment_invoice_allocations','finance_payment_money_allocations','finance_payment_wht_components','finance_payments','finance_payout_allocations','finance_payout_audit','finance_payouts','finance_receipts','finance_tax_document_corrections','finance_tax_filing_allocations