 '3cffbbfbb1a554ef3e3eb9955f438b4f331d831b3209b44c27b796e30ce96e44' candidate_sha256,'5635a8a220628448ca9fd156d692b34bc7d13c8b6b796ce7d3d7cebb8451c464' manifest_sha256,'4c9204bfb7ca94c39c79ce55d56348310fa60d7fb664c63994e6593790a35417' approved_baseline_sha256,
 (select encode(sha256(convert_to((value)::text,'UTF8')),'hex')='4c9204bfb7ca94c39c79ce55d56348310fa60d7fb664c63994e6593790a35417' from normalized) exact_approved_baseline_matched,
 (select encode(sha256(convert_to((value->'rows')::text,'UTF8')),'hex')='4ee66d9d5c5d6660dd5f0d3afef6b4f734aabf252e490a8e066d09ed6a1c7171' from actual) historical_rows_unchanged,
 (select value='[]'::jsonb from diff) applied_state_exact,(select value from diff) object_differences,
 (select coalesce(jsonb_agg(v),'[]') from diff,jsonb_array_elements(value) v where v->>'section'='functions') function_differences,
 (select coalesce(jsonb_agg(v),'[]') from diff,jsonb_array_elements(value) v where v->>'section' in('catalog','views')) catalog_differences
FROM checks;
